-- Generated by theme switcher (matrix)
vim.cmd("hi clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end
vim.g.colors_name = "matrix"
vim.o.background = "dark"

local bg = "#0D0D0D"
local fg = "#00FF41"
local accent = "#00FF41"
local dim = "#00CC33"
local bright = "#39FF14"
local surface = "#0D1A0D"
local comment = "#00802B"
local sel_bg = "#003B00"
local sel_fg = "#00FF41"

local function hi(group, opts)
  vim.api.nvim_set_hl(0, group, opts)
end

hi("Normal", { fg = fg, bg = "NONE" })
hi("NormalFloat", { fg = fg, bg = surface })
hi("NormalNC", { fg = fg, bg = "NONE" })
hi("Directory", { fg = accent, bold = true })
hi("NonText", { fg = comment })
hi("Conceal", { fg = comment })
hi("Comment", { fg = comment, italic = true })
hi("Constant", { fg = bright })
hi("String", { fg = dim })
hi("Identifier", { fg = fg })
hi("Function", { fg = accent })
hi("Statement", { fg = bright })
hi("PreProc", { fg = dim })
hi("Type", { fg = accent })
hi("Special", { fg = bright })
hi("Underlined", { fg = accent, underline = true })
hi("Todo", { fg = sel_fg, bg = accent, bold = true })
hi("LineNr", { fg = comment })
hi("Folded", { fg = fg, bg = surface })
hi("FoldColumn", { fg = comment, bg = "NONE" })
-- Workbench-style selection: white on blue (or theme selection colors)
hi("CursorLine", { bg = sel_bg, fg = sel_fg })
hi("CursorLineNr", { fg = sel_fg, bg = sel_bg, bold = true })
hi("Visual", { bg = sel_bg, fg = sel_fg })
hi("Search", { bg = dim, fg = bg })
hi("IncSearch", { bg = accent, fg = bg })
-- StatusLine feeds lualine auto-theme section C — keep it dark + bright text
hi("StatusLine", { fg = accent, bg = surface, bold = true })
hi("StatusLineNC", { fg = dim, bg = surface })
hi("VertSplit", { fg = comment })
hi("WinSeparator", { fg = comment })
hi("Pmenu", { fg = fg, bg = surface })
-- PmenuSel.bg is lualine auto "normal" accent (mode pill)
hi("PmenuSel", { fg = bg, bg = accent, bold = true })
hi("TelescopeSelection", { fg = sel_fg, bg = sel_bg, bold = true })
hi("TelescopeSelectionCaret", { fg = sel_fg, bg = sel_bg })
-- Snacks explorer / picker: default file names must use Normal fg (not NonText grey)
hi("SnacksPickerFile", { fg = fg })
hi("SnacksPickerDirectory", { fg = accent, bold = true })
hi("SnacksPickerDir", { fg = comment })
hi("SnacksPickerPathHidden", { fg = comment })
hi("SnacksPickerPathIgnored", { fg = comment })
hi("SnacksPickerDimmed", { fg = comment })
hi("SnacksPickerComment", { fg = comment })
hi("SnacksPickerTotals", { fg = comment })
hi("SnacksPickerTree", { fg = comment })
hi("SnacksPickerGitStatusUntracked", { fg = comment })
hi("SnacksPickerGitStatusIgnored", { fg = comment })
hi("SnacksPickerGitStatusAdded", { fg = bright })
hi("SnacksPickerGitStatusModified", { fg = dim })
hi("SnacksPickerGitStatusDeleted", { fg = "#003B00" })
-- Neo-tree fallbacks
hi("NeoTreeNormal", { fg = fg, bg = "NONE" })
hi("NeoTreeNormalNC", { fg = fg, bg = "NONE" })
hi("NeoTreeFileName", { fg = fg })
hi("NeoTreeDirectoryName", { fg = accent, bold = true })
hi("NeoTreeDimText", { fg = comment })
-- Bufferline / tabs: inactive must stay readable (don't use near-black Comment)
hi("TabLine", { fg = dim, bg = bg })
hi("TabLineFill", { fg = dim, bg = bg })
hi("TabLineSel", { fg = sel_fg, bg = sel_bg, bold = true })
hi("BufferLineFill", { fg = dim, bg = bg })
hi("BufferLineBackground", { fg = dim, bg = bg })
hi("BufferLineBuffer", { fg = dim, bg = bg })
hi("BufferLineBufferVisible", { fg = dim, bg = bg })
hi("BufferLineBufferSelected", { fg = sel_fg, bg = sel_bg, bold = true, italic = true })
hi("BufferLineTab", { fg = dim, bg = bg })
hi("BufferLineTabSelected", { fg = sel_fg, bg = sel_bg, bold = true })
hi("BufferLineTabClose", { fg = dim, bg = bg })
hi("BufferLineCloseButton", { fg = dim, bg = bg })
hi("BufferLineCloseButtonVisible", { fg = dim, bg = bg })
hi("BufferLineCloseButtonSelected", { fg = sel_fg, bg = sel_bg })
hi("BufferLineSeparator", { fg = bg, bg = bg })
hi("BufferLineSeparatorVisible", { fg = bg, bg = bg })
hi("BufferLineSeparatorSelected", { fg = sel_bg, bg = sel_bg })
hi("BufferLineIndicatorSelected", { fg = sel_fg, bg = sel_bg })
hi("BufferLineIndicatorVisible", { fg = dim, bg = bg })
hi("BufferLineModified", { fg = dim, bg = bg })
hi("BufferLineModifiedVisible", { fg = dim, bg = bg })
hi("BufferLineModifiedSelected", { fg = sel_fg, bg = sel_bg })
hi("BufferLineDuplicate", { fg = comment, bg = bg, italic = true })
hi("BufferLineDuplicateVisible", { fg = comment, bg = bg, italic = true })
hi("BufferLineDuplicateSelected", { fg = sel_fg, bg = sel_bg, italic = true })
hi("BufferLineNumbers", { fg = dim, bg = bg })
hi("BufferLineNumbersVisible", { fg = dim, bg = bg })
hi("BufferLineNumbersSelected", { fg = sel_fg, bg = sel_bg, bold = true })
hi("BufferLineErrorSelected", { fg = sel_fg, bg = sel_bg, bold = true })
hi("BufferLineErrorDiagnosticSelected", { fg = sel_fg, bg = sel_bg })
hi("BufferLineWarningSelected", { fg = sel_fg, bg = sel_bg, bold = true })
hi("BufferLineWarningDiagnosticSelected", { fg = sel_fg, bg = sel_bg })
hi("BufferLineInfoSelected", { fg = sel_fg, bg = sel_bg })
hi("BufferLineInfoDiagnosticSelected", { fg = sel_fg, bg = sel_bg })
hi("BufferLineHintSelected", { fg = sel_fg, bg = sel_bg })
hi("BufferLineHintDiagnosticSelected", { fg = sel_fg, bg = sel_bg })
hi("DiagnosticError", { fg = "#003B00" })
hi("DiagnosticWarn", { fg = dim })
hi("DiagnosticInfo", { fg = accent })
hi("DiagnosticHint", { fg = bright })
hi("DiffAdd", { fg = bright })
hi("DiffChange", { fg = dim })
hi("DiffDelete", { fg = "#003B00" })
hi("DiffText", { fg = accent, bold = true })

